// Calculate metrics
function getGrade(score) {
  if (score >= 91) return "A";
  if (score >= 81) return "B";
  if (score >= 71) return "C";
  if (score >= 61) return "D";
  if (score >= 51) return "E";
  return "F";
}
function scoreToPoint(score) {
  if (score >= 91) return 4.0;
  if (score >= 81) return 3.0;
  if (score >= 71) return 2.0;
  if (score >= 61) return 1.0;
  return 0.0;
}

/**
 * SCROLL & UI ENGINE (Antigravity Adaptability)
 */
function initScrollEngine() {
  const header = document.getElementById("site-header");
  const toggle = document.getElementById("mobile-toggle");
  const overlay = document.getElementById("mobile-nav");
  const links = document.querySelectorAll(".mobile-nav-link");
  const html = document.documentElement;

  // Parallax Elements
  const heroBg = document.querySelector(".fluid-bg");
  const heroCanvas = document.getElementById("particles-canvas");
  const heroContent = document.querySelector(".hero-content");

  // Header Blur Effect & Parallax
  window.addEventListener(
    "scroll",
    () => {
      const scrolled = window.scrollY;

      // Header
      if (scrolled > 20) {
        header.classList.add("scrolled");
      } else {
        header.classList.remove("scrolled");
      }

      // Hero Parallax Effect (only apply if in viewport)
      if (scrolled < window.innerHeight) {
        if (heroBg) heroBg.style.transform = `translateY(${scrolled * 0.4}px)`;
        if (heroCanvas)
          heroCanvas.style.transform = `translateY(${scrolled * 0.2}px)`;
        if (heroContent) {
          heroContent.style.transform = `translateY(${scrolled * 0.15}px)`;
          heroContent.style.opacity = Math.max(
            0,
            1 - scrolled / (window.innerHeight * 0.8),
          );
        }
      }
    },
    { passive: true },
  );

  // Mobile Toggle
  toggle.addEventListener("click", () => {
    const isActive = toggle.classList.toggle("active");
    overlay.classList.toggle("active");
    html.classList.toggle("scroll-locked");
  });

  const allMobileLinks = document.querySelectorAll(".mobile-nav-link, .mobile-nav-sublink");
  allMobileLinks.forEach((link) => {
    link.addEventListener("click", () => {
      toggle.classList.remove("active");
      overlay.classList.remove("active");
      html.classList.remove("scroll-locked");
    });
  });

  // Reveal Animation (Safe observer: never traps tall sections or hash targets at opacity: 0)
  if (typeof window.syncSafeReveals === "function") {
    window.syncSafeReveals(document.querySelectorAll(".reveal"));
  }
}

/**
 * THEME ENGINE (Multi-Theme Support)
 */

/**
 * THEME ENGINE (Direct Single-Click Dark/Light Toggle)
 */

// Mobile Nav Accordions
const mobileHeaders = document.querySelectorAll(".mobile-nav-header");
mobileHeaders.forEach((btn) => {
  btn.addEventListener("click", () => {
    const parentGroup = btn.closest(".mobile-nav-group");
    if (parentGroup) {
      const isOpen = parentGroup.classList.toggle("open");
      btn.setAttribute("aria-expanded", isOpen ? "true" : "false");
    }
  });
});

// Hash Navigation Handler
function handleHashNavigation() {
  const hash = window.location.hash;
  if (!hash) return;

  if (hash === "#majors" || hash === "#tree-majors-block") {
    if (window.switchStructureView) window.switchStructureView("majors");
  } else if (hash === "#structure" || hash === "#commissions" || hash === "#fbk" || hash === "#struct-commissions-view") {
    if (window.switchStructureView) window.switchStructureView("tree");
  } else if (hash.startsWith("#campus-floor-")) {
    const fl = hash.replace("#campus-floor-", "");
    if (window.switchCampusFloor) window.switchCampusFloor(fl);
    setTimeout(() => {
      const sec = document.getElementById("campus-navigator");
      if (sec) sec.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 80);
  }
}

window.addEventListener("hashchange", handleHashNavigation);
setTimeout(handleHashNavigation, 250);

function setTheme(theme) {
  document.body.classList.remove("light-mode", "dark-mode", "space-mode");
  document.documentElement.classList.remove("light-mode", "dark-mode", "space-mode");

  const normalized = theme === "dark" ? "dark" : "light";
  if (normalized === "dark") {
    document.body.classList.add("dark-mode");
    document.documentElement.classList.add("dark-mode");
  } else {
    document.body.classList.add("light-mode");
    document.documentElement.classList.add("light-mode");
  }

  localStorage.setItem("bdrnk-theme", normalized);
  document.documentElement.setAttribute("data-theme", normalized);

  const themeToggleBtn = document.getElementById("theme-toggle");
  const mobileThemeToggle = document.getElementById("mobile-theme-toggle");
  const cmThemeToggle = document.getElementById("cm-theme-toggle");

  if (themeToggleBtn) {
    themeToggleBtn.setAttribute("aria-label", normalized === "dark" ? "İşıqlı rejimə keç" : "Qaranlıq rejimə keç");
    themeToggleBtn.classList.toggle("is-dark", normalized === "dark");
  }

  if (mobileThemeToggle) {
    mobileThemeToggle.setAttribute("aria-label", normalized === "dark" ? "İşıqlı rejimə keç" : "Qaranlıq rejimə keç");
    mobileThemeToggle.classList.toggle("is-dark", normalized === "dark");
    // No text, symbols only
  }

  document.dispatchEvent(new CustomEvent("themeChanged", { detail: { theme: normalized } }));
}

function initThemeEngine() {
  const themeToggleBtn = document.getElementById("theme-toggle");
  const mobileThemeToggle = document.getElementById("mobile-theme-toggle");
  const cmThemeToggle = document.getElementById("cm-theme-toggle");

  function toggleThemeDirect() {
    const isDark = document.body.classList.contains("dark-mode") || document.documentElement.getAttribute("data-theme") === "dark";
    const next = isDark ? "light" : "dark";
    setTheme(next);
  }

  themeToggleBtn?.addEventListener("click", (e) => {
    e.preventDefault();
    toggleThemeDirect();
  });

  mobileThemeToggle?.addEventListener("click", (e) => {
    e.preventDefault();
    toggleThemeDirect();
  });

  cmThemeToggle?.addEventListener("click", (e) => {
    e.preventDefault();
    toggleThemeDirect();
  });

  // Apply initially saved theme (default to light unless user explicitly chose dark)
  const savedTheme = localStorage.getItem("bdrnk-theme") === "dark" ? "dark" : "light";
  setTheme(savedTheme);
}

